#include <stdio.h>

int main(void) {
    int N, F;
    scanf("%d %d", &N, &F);

    char grid[500][502];
    for (int i = 0; i < N; i++) {
        scanf("%s", grid[i]);
    }

    int qr[250000], qc[250000];
    int front = 0, back = 0;

    if (grid[0][0] - '0' <= F) {
        grid[0][0] = '*';
        qr[back] = 0;
        qc[back] = 0;
        back++;
    }

    int dr[4] = {-1, 1, 0, 0};
    int dc[4] = {0, 0, -1, 1};

    while (front < back) {
        int r = qr[front];
        int c = qc[front];
        front++;

        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k];
            int nc = c + dc[k];

            if (nr < 0 || nr >= N || nc < 0 || nc >= N) continue;
            if (grid[nr][nc] == '*') continue;
            if (grid[nr][nc] - '0' <= F) {
                grid[nr][nc] = '*';
                qr[back] = nr;
                qc[back] = nc;
                back++;
            }
        }
    }

    for (int i = 0; i < N; i++) {
        printf("%s\n", grid[i]);
    }

    return 0;
}
